-- Контрольные запросы набора «Авиаперевозки» для tools/pg-check.sh: выпуск загружен в Postgres, каждый запрос печатает
-- одну строку «что: значение». Первые четыре — инварианты (ждём 0), последний — справка (у full ≈ 73 %).
select 'брони: сумма брони ≠ сумме цен её перелётов — ' || count(*) from (select b.book_ref from bookings b join tickets t on t.book_ref = b.book_ref join segments s on s.ticket_no = t.ticket_no group by b.book_ref, b.total_amount having b.total_amount <> sum(s.price)) x;
select 'брони без билетов, билеты без перелётов — ' || (select count(*) from bookings b where not exists (select 1 from tickets t where t.book_ref = b.book_ref)) || ', ' || (select count(*) from tickets t where not exists (select 1 from segments s where s.ticket_no = t.ticket_no));
select 'рейсы без версии маршрута на плановый вылет — ' || count(*) from flights f where not exists (select 1 from routes r where r.route_no = f.route_no and f.scheduled_departure >= r.valid_from and f.scheduled_departure < r.valid_to);
select 'посадочные: место не из салона самолёта рейса — ' || count(*) from boarding_passes bp join flights f on f.flight_id = bp.flight_id join routes r on r.route_no = f.route_no and f.scheduled_departure >= r.valid_from and f.scheduled_departure < r.valid_to where not exists (select 1 from seats st where st.airplane_code = r.airplane_code and st.seat_no = bp.seat_no);
select 'загрузка прилетевших рейсов (проданные места к местам в самолёте): ' || coalesce(round(100.0 * sum(sold) / nullif(sum(cap), 0), 1)::text, '—') || ' %' from (select (select count(*) from segments s where s.flight_id = f.flight_id) sold, (select count(*) from seats st where st.airplane_code = r.airplane_code) cap from flights f join routes r on r.route_no = f.route_no and f.scheduled_departure >= r.valid_from and f.scheduled_departure < r.valid_to where f.status = 'Arrived') x;
